; Display list

dlist = *
	; :6 dta $70	; 6 empty lines
	.repeat 6, I
	.byte	$70
	.endrep
	; ANTIC mode 2, for the first line of infos drawn on the screen
	.byte	$42
	.word	line_0
	.byte	$70	; 1 empty line
	; :4 dta $06	; ANTIC mode 6, 4 lines, for the volume bars
	.repeat 4, I
	.byte	$06
	.endrep
	; :7 dta $02	; All the middle part is back to mode 2, for all the infos and song buttons display
	.repeat 7, I
	.byte	$02
	.endrep
	.byte	$70	; 1 empty line
	; :3 dta $02	; 3 lines of user input text from RMT
	.repeat 3, I
	.byte	$02
	.endrep
	.byte	$42
txt_toggle = *
	.word	line_4	; Memory address set to line_4 by default, or line_5 when SHIFT is held
	; :3 dta $70	; 3 empty lines
	.repeat 3, I
	.byte	$70
	.endrep
	; 1 final line of mode 2, must have its own addressing or else the SHIFT toggle affects it
	.byte	$42
	.word	line_6
	; Jump and wait for vblank, return to dlist
	.byte	$41
	.word	dlist

